        Loc.Add("rivers.finish", "Finish river", "Fluss fertigstellen", "Terminar río", "Terminer la rivière", "Completa fiume", "Завершить реку", "完成河流");
        Loc.Add("rivers.cancelPending", "Cancel pending river", "Ausstehenden Fluss abbrechen", "Cancelar río pendiente", "Annuler la rivière en cours", "Annulla fiume in sospeso", "Отменить незавершённую реку", "取消待处理的河流");
        Loc.Add("rivers.deleteSelected", "Delete selected river segment", "Ausgewähltes Flusssegment löschen", "Eliminar segmento de río seleccionado", "Supprimer le segment de rivière sélectionné", "Elimina segmento fiume selezionato", "Удалить выбранный сегмент реки", "删除所选河流段");
        Loc.Add("rivers.clearAll", "Clear ALL rivers", "ALLE Flüsse löschen", "Eliminar TODOS los ríos", "Supprimer TOUTES les rivières", "Cancella TUTTI i fiumi", "Удалить ВСЕ реки", "清除所有河流");
        Loc.Add("rivers.discardImported", "Discard imported river background", "Importierten Fluss-Hintergrund verwerfen", "Descartar fondo de ríos importado", "Ignorer le fond de rivières importé", "Scarta sfondo fiumi importato", "Отклонить импортированный фон рек", "放弃导入的河流背景");
        Loc.Add("rivers.showGrid", "Show 128px grid", "128px-Raster anzeigen", "Mostrar cuadrícula de 128px", "Afficher la grille de 128px", "Mostra griglia 128px", "Показать сетку 128px", "显示128像素网格");
        Loc.Add("rivers.autoGroup", "Auto-generate", "Automatisch generieren", "Generar automáticamente", "Génération automatique", "Generazione automatica", "Автогенерация", "自动生成");
        Loc.Add("rivers.autoCount", "River count", "Anzahl Flüsse", "Cantidad de ríos", "Nombre de rivières", "Numero di fiumi", "Количество рек", "河流数量");
        Loc.Add("rivers.autoCount.tip",
            "How many source rivers to attempt when auto-generating (actual count may be lower - a walk that never reaches water is discarded).",
            "Wie viele Quellflüsse bei der automatischen Generierung versucht werden (tatsächliche Anzahl kann niedriger sein - ein Verlauf, der nie Wasser erreicht, wird verworfen).",
            "Cuántos ríos de origen se intentan al generar automáticamente (la cantidad real puede ser menor - un recorrido que nunca alcanza agua se descarta).",
            "Combien de rivières sources sont tentées lors de la génération automatique (le nombre réel peut être inférieur - un tracé qui n'atteint jamais l'eau est écarté).",
            "Quanti fiumi sorgente vengono tentati nella generazione automatica (il numero effettivo potrebbe essere inferiore - un percorso che non raggiunge mai l'acqua viene scartato).",
            "Сколько истоков рек пытается создать автогенерация (фактическое число может быть меньше - путь, никогда не достигающий воды, отбрасывается).",
            "自动生成时尝试的河流源头数量（实际数量可能更少——始终未到达水域的路径会被丢弃）。");
        Loc.Add("rivers.autoGenerate", "Regenerate rivers", "Flüsse neu generieren", "Regenerar ríos", "Régénérer les rivières", "Rigenera fiumi", "Пересоздать реки", "重新生成河流");
        Loc.Add("rivers.regenSame", "Regenerate (same seed)", "Neu generieren (gleicher Seed)", "Regenerar (misma semilla)", "Régénérer (même graine)", "Rigenera (stesso seme)", "Пересоздать (тот же сид)", "重新生成（相同种子）");
        Loc.Add("rivers.regenSame.tip", "Uses the tile's seed with the current slider values. Same settings give the same rivers.", "Nimmt den Seed der Kachel mit den aktuellen Reglerwerten. Gleiche Einstellungen ergeben gleiche Flüsse.", "Usa la semilla del tile con los valores actuales. Los mismos ajustes dan los mismos ríos.", "Utilise la graine de la tuile avec les réglages actuels. Mêmes réglages, mêmes rivières.", "Usa il seme del tile con i valori attuali. Stesse impostazioni, stessi fiumi.", "Использует сид тайла с текущими значениями ползунков. Те же настройки дают те же реки.", "使用地块种子和当前滑块值。相同设置生成相同河流。");
        Loc.Add("rivers.regenNew", "Regenerate (new seed)", "Neu generieren (neuer Seed)", "Regenerar (nueva semilla)", "Régénérer (nouvelle graine)", "Rigenera (nuovo seme)", "Пересоздать (новый сид)", "重新生成（新种子）");
        Loc.Add("rivers.regenNew.tip", "Draws a completely new river network. The tile's seed stays unchanged.", "Erzeugt ein komplett neues Flussnetz. Der Seed der Kachel bleibt unverändert.", "Genera una red de ríos totalmente nueva. La semilla del tile no cambia.", "Crée un réseau de rivières entièrement nouveau. La graine de la tuile reste inchangée.", "Crea una rete fluviale del tutto nuova. Il seme del tile resta invariato.", "Создаёт совершенно новую речную сеть. Сид тайла не меняется.", "生成全新的河网。地块种子保持不变。");

