        Loc.Add("specialFeatures.instr.regions", "Click a province to add or remove it as a region seed.", "Eine Provinz anklicken, um sie als Region-Startpunkt hinzuzufügen oder zu entfernen.", "Haz clic en una provincia para añadirla o quitarla como semilla de región.", "Cliquez sur une province pour l'ajouter ou la retirer comme graine de région.", "Clicca su una provincia per aggiungerla o rimuoverla come seme di regione.", "Щёлкните по провинции, чтобы добавить или убрать её как зерно региона.", "点击省份可将其添加或移除为区域种子点。");
        Loc.Add("specialFeatures.instr.names", "Click a province to set or change its name (leave the text empty to remove it).", "Eine Provinz anklicken, um ihren Namen festzulegen oder zu ändern (leeres Textfeld entfernt ihn).", "Haz clic en una provincia para poner o cambiar su nombre (deja el texto vacío para quitarlo).", "Cliquez sur une province pour définir ou modifier son nom (laissez le texte vide pour le supprimer).", "Clicca su una provincia per impostare o cambiare il suo nome (lascia il testo vuoto per rimuoverlo).", "Щёлкните по провинции, чтобы задать или изменить её название (пустой текст удаляет его).", "点击省份可设置或更改其名称（留空文本可移除名称）。");
        Loc.Add("specialFeatures.instr.modifiers", "Click a province to assign a modifier to it.", "Eine Provinz anklicken, um ihr einen Modifikator zuzuweisen.", "Haz clic en una provincia para asignarle un modificador.", "Cliquez sur une province pour lui attribuer un modificateur.", "Clicca su una provincia per assegnarle un modificatore.", "Щёлкните по провинции, чтобы назначить ей модификатор.", "点击省份可为其指定修正效果。");
        Loc.Add("specialFeatures.instr.wrongKindLand", "That's not a land province - click a land province instead.", "Das ist keine Landprovinz - bitte eine Landprovinz anklicken.", "Esa no es una provincia terrestre - haz clic en una provincia terrestre.", "Ce n'est pas une province terrestre - cliquez sur une province terrestre.", "Non è una provincia di terra - clicca su una provincia di terra.", "Это не сухопутная провинция - щёлкните по сухопутной провинции.", "这不是陆地省份——请点击一个陆地省份。");
        Loc.Add("specialFeatures.instr.wrongKindSea", "That's not a sea/lake province - click the connecting water province instead.", "Das ist keine See-/Binnensee-Provinz - bitte die verbindende Wasserprovinz anklicken.", "Esa no es una provincia marítima/lacustre - haz clic en la provincia de agua que conecta.", "Ce n'est pas une province maritime/lacustre - cliquez sur la province d'eau de liaison.", "Non è una provincia di mare/lago - clicca sulla provincia d'acqua di collegamento.", "Это не морская/озёрная провинция - щёлкните по соединяющей водной провинции.", "这不是海洋/湖泊省份——请点击连接用的水域省份。");
        Loc.Add("specialFeatures.instr.sameProvince", "Pick a DIFFERENT land province than the first one.", "Eine ANDERE Landprovinz als die erste wählen.", "Elige una provincia terrestre DISTINTA a la primera.", "Choisissez une province terrestre DIFFÉRENTE de la première.", "Scegli una provincia di terra DIVERSA dalla prima.", "Выберите ДРУГУЮ сухопутную провинцию, отличную от первой.", "请选择与第一个不同的陆地省份。");
        Loc.Add("specialFeatures.hoverBase", "Province #{0} ({1})", "Provinz #{0} ({1})", "Provincia n.º {0} ({1})", "Province n° {0} ({1})", "Provincia n. {0} ({1})", "Провинция №{0} ({1})", "省份 #{0}（{1}）");
